package com.circlenet.domain.person;import java.security.Principal;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/people") public class PersonProfileController {private final PersonProfileService service;public PersonProfileController(PersonProfileService s){service=s;}private Long id(Principal p){return Long.valueOf(p.getName());}
 @GetMapping("/{personId}/profile")public PersonDtos.Profile get(Principal p,@PathVariable Long personId){return service.get(id(p),personId);}@PutMapping("/{personId}/record")public PersonDtos.Profile save(Principal p,@PathVariable Long personId,@RequestBody PersonDtos.Record value){return service.save(id(p),personId,value);}
 @PostMapping(value="/{personId}/photo",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public PersonDtos.Profile photo(Principal p,@PathVariable Long personId,@RequestPart("file")MultipartFile file){return service.uploadProfilePhoto(id(p),personId,file);}
 @PostMapping(value="/{personId}/memories",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public PersonDtos.Memory memory(Principal p,@PathVariable Long personId,@RequestParam(required=false)String title,@RequestParam(required=false)String note,@RequestPart(required=false)MultipartFile file){return service.addMemory(id(p),personId,title,note,file);}@DeleteMapping("/{personId}/memories/{memoryId}")public ResponseEntity<Void> delete(Principal p,@PathVariable Long personId,@PathVariable Long memoryId){service.deleteMemory(id(p),personId,memoryId);return ResponseEntity.noContent().build();}
 @GetMapping("/{personId}/memories/{memoryId}/media")public ResponseEntity<org.springframework.core.io.Resource> media(Principal p,@PathVariable Long personId,@PathVariable Long memoryId){var a=service.attachment(id(p),personId,memoryId);return ResponseEntity.ok().contentType(MediaType.parseMediaType(a.type())).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.inline().filename(a.name()).build().toString()).body(a.resource());}}
